<!-- Multiple inline children in a multiline inline parent: the void element and the text after it
     are isolated by an authored newline, which flows back onto the content line -->
<div>
	<label for="id" class="class1 class2 class3 class4 class5 class6 class7 class8" data-attr="value">
		<input type="checkbox" /> text1 text2
	</label>
</div>
